  slug: 'secp-compliance-calendar-private-limited-company-pakistan',
  title: 'SECP Compliance Calendar for a Private Limited Company — Every Recurring Filing Tracked | Kamboh Associates',
  ogTitle: 'SECP Compliance Calendar for a Private Limited Company',
  metaDesc: 'A practical, recurring SECP compliance calendar for a private limited company in Pakistan — every filing that repeats year after year, tracked against its own trigger.',
